<script setup lang="ts">
const db=useDb(),w=useWorkspace(),search=ref(''),editing=ref<Record<string,any>|null>(null),related=ref<any[]>([]),{error,busy,run}=useAction()
const {data,refresh}=await useAsyncData('customers',async()=>check(await db.from('quolyn_customers').select('*').eq('workspace_id',w.value!.id).order('name')))
const rows=computed(()=>data.value?.filter(c=>c.name.toLowerCase().includes(search.value.toLowerCase())))
async function edit(c?:Record<string,any>){editing.value=c?{...c}:{name:'',currency:w.value!.currency,discount_bps:0};related.value=[];if(c){const r=await Promise.all([db.from('quolyn_enquiries').select('id,title').eq('customer_id',c.id),db.from('quolyn_quotes').select('id,number,status').eq('customer_id',c.id)]);related.value=[...(check(r[0]!)||[]).map(x=>({id:x.id,label:x.title,path:'/enquiries/'})),...(check(r[1]!)||[]).map(x=>({id:x.id,label:x.number+' · '+x.status,path:'/quotes/'}))]}}
async function save(){await run(async()=>{check(await db.from('quolyn_customers').upsert({...editing.value,workspace_id:w.value!.id}));editing.value=null;await refresh()})}
</script>
<template><div><div class="page-title"><div><div class="eyebrow">BUSINESS RELATIONSHIPS</div><h1>Customers</h1><p>Keep commercial details close to the quotation.</p></div><button class="primary" @click="edit()">＋ Add customer</button></div><div class="toolbar"><input v-model="search" aria-label="Search customers" placeholder="Search customers…"></div><div class="table-wrap"><table v-if="rows?.length"><thead><tr><th>BUSINESS</th><th>CONTACT</th><th>CURRENCY</th><th>DEFAULT DISCOUNT</th><th></th></tr></thead><tbody><tr v-for="c in rows" :key="c.id"><td>{{c.name}}<small>{{c.address||'Address not added'}}</small></td><td>{{c.contact_name||'—'}}<small>{{c.email}}</small></td><td>{{c.currency}}</td><td>{{c.discount_bps/100}}%</td><td><button class="link" @click="edit(c)">View / edit →</button></td></tr></tbody></table><div v-else class="empty"><div class="empty-icon">♧</div><h3>Your next relationship starts here</h3><p>Add a customer to prepare their first quotation.</p><button class="secondary" @click="edit()">Add customer</button></div></div><template v-if="editing"><div class="drawer-backdrop" @click="editing=null"></div><aside class="drawer"><div class="row between"><h2>Customer details</h2><button class="secondary mini" @click="editing=null">Close</button></div><form @submit.prevent="save"><label>Business name<input v-model="editing.name" required></label><label>Contact name<input v-model="editing.contact_name"></label><div class="form-grid"><label>Email<input v-model="editing.email" type="email"></label><label>Phone<input v-model="editing.phone"></label></div><label>Billing address<textarea v-model="editing.address"></textarea></label><label>Tax reference<input v-model="editing.tax_reference"></label><div class="form-grid"><label>Currency<input v-model="editing.currency" required maxlength="3"></label><label>Discount basis points<input v-model.number="editing.discount_bps" type="number" min="0" max="10000" required></label></div><p class="muted">500 basis points = 5%. A manual line discount replaces this default.</p><label>Payment terms<input v-model="editing.payment_terms"></label><label>Internal notes<textarea v-model="editing.notes"></textarea></label><p class="error" role="alert">{{error}}</p><button class="primary" :disabled="busy">Save customer</button></form><h3 style="margin-top:30px">Related records</h3><NuxtLink v-for="r in related" :key="r.id" :to="r.path+r.id" class="link" style="display:block">{{r.label}} →</NuxtLink></aside></template></div></template>
